from pathlib import Path
import json, base64

repo = Path(__file__).resolve().parents[4]
config = json.loads(Path(__file__).with_name('gallery-data.json').read_text())
template = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenSnap glass choices</title><style>
:root{font-family:var(--font-sans,system-ui);color:var(--foreground,CanvasText);color-scheme:light dark}*{box-sizing:border-box}body{margin:0;background:transparent;font-size:20px;line-height:1.5}h1{font-size:30px;line-height:1.25}h2{font-size:25px;line-height:1.3}h3{font-size:21px}p{margin:12px 0}button,input,select,summary{font:inherit;font-size:20px}button,select,input{min-height:44px;max-width:100%;border:1px solid var(--border,#888);border-radius:10px;padding:8px 12px;background:var(--card,Canvas);color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button[aria-pressed=true]{border-color:var(--accent,#ba8000);background:var(--accent-surface,#ffe9ac);color:var(--accent-surface-foreground,#302500)}:focus-visible{outline:3px solid var(--ring,#c18b00);outline-offset:3px}.meta{font-size:18px;color:var(--muted-foreground,CanvasText);overflow-wrap:anywhere}.panel{border:1px solid var(--border,#bbb);border-radius:16px;padding:18px;margin:24px 0;background:var(--card,Canvas)}.tools{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:16px 0}.tools>*{flex:0 1 auto}.tools select{flex:1 1 160px}.preview{overflow:auto;border-radius:12px;border:1px solid var(--border,#bbb);max-height:760px}.preview img{display:block;width:100%;height:auto}.preview.native img{width:auto;max-width:none}.thumbs{display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:12px;max-height:440px;overflow:auto;padding:4px}.thumb{display:flex;flex-direction:column;text-align:left;gap:8px;padding:10px;font-size:18px;width:100%}.thumb img{display:block;width:100%;height:105px;object-fit:contain;background:var(--secondary,#ddd);border-radius:7px}.thumb.selected{border-color:var(--accent,#b87d00);outline:2px solid var(--accent,#b87d00)}.compare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.compare img{display:block;width:100%;height:auto;border:1px solid var(--border,#aaa);border-radius:10px}.compare h3{font-size:20px}.note{padding-left:14px;border-left:3px solid var(--accent,#b87d00)}@media(max-width:520px){.compare{grid-template-columns:1fr}.panel{padding:16px}.tools button{flex:1 1 auto}}[hidden]{display:none!important}</style></head><body>
<h1 id="title"></h1><p id="status" class="note"></p><p id="detail"></p>
<section class="panel" aria-label="Picker evidence gallery"><h2>Picker gallery</h2><div class="tools"><select id="area" aria-label="Filter by picker"><option value="all">All pickers</option></select><select id="phase" aria-label="Filter by implementation phase"><option value="all">Before and after</option><option>Before</option><option>After</option></select><select id="appearance" aria-label="Filter by app appearance"><option value="all">Light and dark</option><option value="light">Light</option><option value="dark">Dark</option></select><button id="favorites" aria-pressed="false">Favorites only</button></div><div class="tools"><button id="favorite" aria-pressed="false">Favorite</button><button id="compare">Add to comparison</button><button id="download">Download capture</button><select id="scale" aria-label="Image scale"><option value="fit">Fit preview</option><option value="native">Stored pixels</option></select></div><h3 id="label"></h3><div class="preview" id="preview"><img id="hero" alt=""></div><p id="provenance" class="meta"></p><p id="state" class="meta"></p><div class="tools"><button id="shortlist">Download shortlist</button></div><div class="thumbs" id="thumbs" aria-label="Capture thumbnails"></div><p id="empty" hidden>No captures match these filters.</p><h2>Side-by-side comparison</h2><p class="meta">Choose up to two captures for comparison. Every view retains its source and implementation phase.</p><div id="comparison" class="compare"></div><div class="tools"><button id="clear">Clear comparison</button></div></section>
<section class="panel"><h2>Verification scope</h2><p id="summary"></p><p class="meta">These are synthetic app-owned captures. A rendered state does not establish real mouse, keyboard, VoiceOver or hardware behavior.</p></section>
<script>const DATA=__DATA__;const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=DATA.defaultSelected??0,onlyFavorites=false,comparisons=DATA.defaultCompare||[],favoriteIds;try{favoriteIds=new Set(JSON.parse(localStorage.getItem('opensnap-glass-picker-favorites')||'[]'))}catch{favoriteIds=new Set()}
function store(){try{localStorage.setItem('opensnap-glass-picker-favorites',JSON.stringify([...favoriteIds]))}catch{}}
function download(name,content,type='application/json'){const a=document.createElement('a');a.download=name;a.href=URL.createObjectURL(new Blob([content],{type}));a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function render(){const filtered=DATA.shots.filter(s=>($('area').value==='all'||s.area===$('area').value)&&($('phase').value==='all'||s.phase===$('phase').value)&&($('appearance').value==='all'||s.appearance===$('appearance').value)&&(!onlyFavorites||favoriteIds.has(s.id)));if(filtered.length&&!filtered.some(s=>s.id===selected))selected=filtered[0].id;const shot=filtered.find(s=>s.id===selected);for(const id of ['preview','label','provenance','state'])$(id).hidden=!shot;for(const id of ['favorite','compare','download','scale'])$(id).disabled=!shot;if(shot){$('label').textContent=shot.phase+' · '+shot.label;$('hero').src=shot.src;$('hero').alt=shot.state;$('provenance').textContent=shot.kind+' · source '+shot.sha;$('state').textContent=shot.state;$('favorite').setAttribute('aria-pressed',favoriteIds.has(shot.id));$('compare').textContent=comparisons.includes(shot.id)?'Remove from comparison':'Add to comparison';$('compare').disabled=!comparisons.includes(shot.id)&&comparisons.length>=2;}
$('empty').hidden=filtered.length>0;$('thumbs').innerHTML='';for(const s of filtered){const b=document.createElement('button');b.className='thumb'+(s.id===selected?' selected':'');b.setAttribute('aria-label',s.phase+' '+s.label);b.setAttribute('aria-pressed',s.id===selected);b.innerHTML='<img alt="" src="'+esc(s.src)+'"><span>'+esc(s.phase+' · '+s.label)+'</span>';b.onclick=()=>{selected=s.id;render()};$('thumbs').appendChild(b)}
$('comparison').innerHTML=comparisons.map(id=>{const s=DATA.shots[id];return '<div><h3>'+esc(s.phase+' · '+s.label)+'</h3><img src="'+esc(s.src)+'" alt="'+esc(s.state)+'"><p class="meta">'+esc('Source '+s.sha+' · '+s.kind)+'</p></div>'}).join('');}
$('title').textContent=DATA.title;$('status').textContent=DATA.status;$('detail').textContent=DATA.detail;$('summary').textContent=DATA.summary;for(const area of new Set(DATA.shots.map(s=>s.area))){const o=document.createElement('option');o.value=o.textContent=area;$('area').appendChild(o)}
if(DATA.defaultPhase)$('phase').value=DATA.defaultPhase;$('area').onchange=$('phase').onchange=$('appearance').onchange=render;$('favorite').onclick=()=>{favoriteIds.has(selected)?favoriteIds.delete(selected):favoriteIds.add(selected);store();render()};$('favorites').onclick=()=>{onlyFavorites=!onlyFavorites;$('favorites').setAttribute('aria-pressed',onlyFavorites);render()};$('compare').onclick=()=>{comparisons=comparisons.includes(selected)?comparisons.filter(id=>id!==selected):[...comparisons,selected].slice(0,2);render()};$('clear').onclick=()=>{comparisons=[];render()};$('scale').onchange=()=>$('preview').classList.toggle('native',$('scale').value==='native');$('shortlist').onclick=()=>download('opensnap-glass-picker-shortlist.json',JSON.stringify(DATA.shots.filter(s=>favoriteIds.has(s.id)).map(({src,...s})=>s),null,2));$('download').onclick=()=>{const s=DATA.shots[selected],a=document.createElement('a');a.href=s.src;a.download=s.name;a.click()};render();{const readable=[...document.querySelectorAll('body *')].filter(e=>e.textContent.trim()&&e.getClientRects().length);console.log(JSON.stringify({readableFontMinimum:Math.min(...readable.map(e=>parseFloat(getComputedStyle(e).fontSize))),undersized:readable.filter(e=>parseFloat(getComputedStyle(e).fontSize)<18).length,horizontalOverflow:document.documentElement.scrollWidth>innerWidth,shots:DATA.shots.length}));};
</script></body></html>'''

for embed, path in [(True, repo / 'docs/design/glass-pickers-gallery.html'), (False, Path('/private/tmp/opensnap-glass-gallery-inline.html'))]:
    data = json.loads(json.dumps(config))
    for shot in data['shots']:
        image = repo / shot['path']
        assert image.exists(), image
        shot['src'] = ('data:image/png;base64,'+base64.b64encode(image.read_bytes()).decode()) if embed else shot['path']
    path.write_text(template.replace('__DATA__',json.dumps(data,separators=(',',':'),ensure_ascii=False)))
print('Gallery built with explicit source and phase labels')
